const markdownStyles=document.createElement('style');markdownStyles.textContent=SAFE_MARKDOWN_CSS;document.head.append(markdownStyles);

const bridge=window.analytics||createSyntheticBridge(),app=document.getElementById('app');
const navigation=[['overview','◈'],['activity','▥'],['models','◎'],['content','⌘'],['structure','▤'],['tools','⚒'],['quality','◇'],['explorer','⌕'],['settings','⚙']];
const defaults={range:'all',branch:'selected',perspective:'unique',timeZone:'local'};
let state={settings:{language:'en',appearance:'system',uiPalette:'default',codeTheme:'default'},sources:[],conversations:[],savedViews:[],annotations:{aliases:{},exclusions:[],groups:{}},job:null},filters={...defaults},report=null,workspace='overview',dialog=null,evidence=[],evidenceTitle='',evidenceTotal=0,evidenceOpen=false,evidenceRequestId=0,computing=false,comparison=null,compareDraft={left:{...defaults},right:{...defaults}},compareChoice={left:'current',right:'current'},requestId=0,latestReportId=0,timelineMode='daily',sortKey='characters',sortOrder='desc',tableQueries={},tablePages={},renderedTableRows={},toastTimer;
let t=translator('en'),nf=new Intl.NumberFormat('en-GB');
let booting=true,bootstrapReady=false,bootstrapPending=false,pendingUpdates=[],payloadRevision=-1,dialogGeneration=0,latestCompareId=0;
ensureBootShell();attachSeriesHover(document);attachStackedBarHover(document);
let explorerSubview='distributions',explorerChart=null,explorerConfig={...EXPLORER_DEFAULTS,chartControls:{}},explorerPages={},explorerQueries={},appliedComparison=null;
