const storageSize=value=>formatStorageSize(value,{locale:localeFor(state.settings.language),bytesLabel:t('bytes'),unavailableLabel:t('unavailable')});
const translatedCategory=value=>t(({tool_call:'tool-call',tool_output:'tool-output',redacted:'redacted-thinking',system:'other'})[value]||value||'unknown');
function label(value){if(typeof value==='string'){const translated=translateExplorerValue(state.settings.language,value);if(translated!==value)return translated;}if(typeof value==='boolean')return t(value?'available':'unavailable');if(value==null||value==='')return t('unknown');const special={'Unknown model':'unknown','Unknown platform':'unknown','Unknown':'unknown','Unknown format':'unknown','Unknown source':'unknown','Recorded missing':'unavailable','Recorded available':'available','recorded-event':'recorded','explicit-source-duration':'recorded','recap (not total compute)':'recap','Unicode code points per observed content segment':'characters','Content segments':'segments','Original message objects':'objects','Request usage':'usage','Context occupancy':'context','Unknown developer':'unknown','Summary-only exported thinking':'summaryOnly','Unavailable thinking representation':'unavailable','Unavailable original trace':'unavailable','Observed exported trace':'trace','Recorded context occupancy':'context','Context occupancy; not consumed or billable usage':'nonBillable','Recorded recap duration':'recap','Recorded duration':'timing','Recorded search event':'search',trace:'trace',summary:'summaryOnly',unavailable:'unavailable',thinkingTrace:'thinking',Sunday:'weekDay0',Monday:'weekDay1',Tuesday:'weekDay2',Wednesday:'weekDay3',Thursday:'weekDay4',Friday:'weekDay5',Saturday:'weekDay6',provider:'platform',source:'sources',format:'formats',collection:'collections',tokens:'tokens',bytes:'bytes',milliseconds:'milliseconds',request:'usage',context:'context',generation:'usage',original:'original',normalized:'normalized',partial:'partial',recorded:'recorded',derived:'derived'};if(special[value])return t(special[value]);if(['user','response','thinking','recap','commentary','tool_call','tool_output','redacted','system','other'].includes(value))return translatedCategory(value);return String(value);}
function dateFmt(value){if(value==null)return t('undated');try{return new Intl.DateTimeFormat(localeFor(state.settings.language),{dateStyle:'medium',timeStyle:'short',timeZone:filters.timeZone==='local'?undefined:filters.timeZone}).format(new Date(value));}catch{return t('undated');}}
const icon='<svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M5 26V18M12 26V12M19 26V5M26 26V15" stroke="currentColor" stroke-width="4" stroke-linecap="round"/><path d="M4 7l8-3 7 1 8-2" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>';
