const checked=value=>value?' checked':'';
const option=(value,name,current)=>`<option value="${attr(value)}"${selected(value,current)}>${esc(name)}</option>`;
const options=(items,current)=>items.map(x=>typeof x==='string'?option(x,label(x),current):option(x.value,x.label,current)).join('');
const action=(name,text,extra='',css='')=>`<button data-action="${attr(name)}" ${extra} class="${css}">${esc(text)}</button>`;
function rows(key){return report?.tables?.[key]||[];}
const tableIndexCache=new WeakMap();
function tableIndex(data){let indexes=tableIndexCache.get(data);if(!indexes){indexes=new Map();data.forEach((row,index)=>{if(!indexes.has(row))indexes.set(row,index);});tableIndexCache.set(data,indexes);}return indexes;}
function activeCount(){return Object.entries(filters).filter(([k,v])=>v!=null&&v!==''&&(Array.isArray(v)?v.length:k==='range'?v!=='all':k==='branch'?v!=='selected':k==='perspective'?v!=='unique':!['timeZone','language','exclusions','excludedConversationIds','aliases'].includes(k))).length;}
function mergedFilters(selection=filters){const annotations=state.annotations||{},groups=annotations.groups||{},groupIds=selection.virtualGroup?(groups[selection.virtualGroup]||[]):null;return {...selection,language:state.settings.language,excludedConversationIds:annotations.exclusions||[],conversationIds:groupIds,displayAliases:annotations.aliases||{},aliases:annotations.dedupAliases||{},modelFamilyAliases:annotations.modelFamilyAliases||{}};}
const workerSource=window.__ANALYTICS_WORKER_SOURCE__;
let worker;
function startWorker(){
 try{worker=workerSource?new Worker(URL.createObjectURL(new Blob([workerSource],{type:'text/javascript'}))):new Worker(new URL('./analytics-worker.js',import.meta.url),{type:'module'});worker.addEventListener('message',handleWorkerMessage);worker.addEventListener('error',handleWorkerFailure);return true;}
 catch{worker=null;return false;}
}
function bootLabels(){if(booting)setBootLabels({loading:t('bootLoading'),retry:t('bootRetry')});}
function bootFailure(){bootstrapReady=false;computing=false;showBootFailure({message:t('bootFailed'),detail:t('bootRetryHelp'),retryLabel:t('bootRetry'),onRetry:bootstrap});}
function finishBoot(){if(!booting||!bootstrapReady||computing||!report)return;requestAnimationFrame(()=>{if(!booting||!bootstrapReady||computing||!report)return;render();revealBootScreen();booting=false;});}
function calculate(){if(!worker){if(booting)bootFailure();else{state.error=true;render();showToast(t('errorMessage'));}return;}computing=true;latestReportId=++requestId;worker.postMessage({type:'report',requestId:latestReportId,filters:mergedFilters(),options:{capturedAt:state.sources.at(-1)?.capturedAt,snapshotComplete:state.sources.every(s=>s.status!=='partial'),explorer:{...explorerConfig,...(state.preview?{usageAudits:Object.fromEntries(state.conversations.filter(c=>c.records.some(r=>r.usage)).map(c=>['synthetic-'+c.provider,{status:'verified',provider:c.provider,scope:'request',unit:'tokens',fields:{inputTokens:'input',outputTokens:'output',cachedTokens:'cached-overlap'}}]))}:{}),...(appliedComparison?{comparisonFiltersA:mergedFilters(appliedComparison.left),comparisonFiltersB:mergedFilters(appliedComparison.right)}:{})}}});render();}
function handleWorkerMessage({data}){
 if(data.type==='report'&&data.requestId===latestReportId){report=data.report;computing=false;render();if(evidenceOpen&&evidenceQuery)requestEvidence();finishBoot();}
 if(data.type==='evidence'&&data.requestId===evidenceRequestId){evidence=data.evidence;evidenceTotal=data.total;evidenceOffset=data.offset??evidenceOffset;evidenceLoading=false;renderEvidence();}
 if(data.type==='compare'&&data.requestId===latestCompareId&&dialog?.type==='compare'){comparison=data.result;renderDialog();}
 if(data.type==='error'){if(data.requestId!==latestReportId)return;computing=false;if(booting)bootFailure();else{showToast(t('errorMessage'));render();}}
}
function handleWorkerFailure(){worker?.terminate();worker=null;computing=false;if(booting)bootFailure();else{state.error=true;showToast(t('errorMessage'));render();}}
function ingest(payload){
 if(typeof payload==='string'){try{payload=JSON.parse(payload);}catch{if(booting)bootFailure();else showToast(t('errorMessage'));return;}}
 if(!payload||typeof payload!=='object')return;
 if(Number.isFinite(payload.__updateRevision)){if(payload.__updateRevision<=payloadRevision)return;payloadRevision=payload.__updateRevision;}
 const hasData=Object.hasOwn(payload,'conversations');state={...state,...payload,settings:{...state.settings,...payload.settings}};
 t=translator(state.settings.language);nf=new Intl.NumberFormat(localeFor(state.settings.language));applyAppearance(state.settings);bootLabels();
 if(hasData){worker?.postMessage({type:'data',conversations:state.conversations});calculate();}
 else render();
}
function receiveUpdate(payload){if(!bootstrapReady){pendingUpdates.push(payload);return;}ingest(payload);}
(bridge.onSerializedUpdate||bridge.onUpdate)?.(receiveUpdate);
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>applyAppearance(state.settings));
async function bootstrap(){
 if(bootstrapPending)return;bootstrapPending=true;bootstrapReady=false;showBootLoading({loading:t('bootLoading'),retry:t('bootRetry')});
 try{if(!worker&&!startWorker())throw new Error('Worker unavailable');let data=await(bridge.bootstrapSerialized||bridge.bootstrap)();if(typeof data==='string')data=JSON.parse(data);filters.timeZone=data.settings?.timezone||'local';state.error=false;bootstrapReady=true;payloadRevision=-1;ingest(data);const queued=pendingUpdates;pendingUpdates=[];for(const update of queued)ingest(update);finishBoot();}
 catch{bootstrapReady=false;bootFailure();}
 finally{bootstrapPending=false;}
}
bootstrap();
function showToast(message){document.querySelector('.toast')?.remove();const node=document.createElement('div');node.className='toast';node.setAttribute('role','status');node.textContent=message;document.body.append(node);clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.remove(),5000);}
async function run(fn,message){try{const result=await fn();if(message)showToast(t(message));return result}catch(error){const code=String(error.code||error.message||'');const key=/ENOSPC|disk.full/i.test(code)?'diskFull':/EACCES|EPERM|permission/i.test(code)?'permission':/overlap|alias/i.test(code)?'sourceOverlap':/unavailable|ENOENT/i.test(code)?'sourceUnavailable':/changed|retry/i.test(code)?'sourceChanged':/cancel/i.test(code)?'cancelled':'errorMessage';showToast(t(key));return null;}}
function render(){
 const previous=captureViewState(app);app.dataset.viewContext=workspace;
 const source=state.sources[0],summary=report?.summary;
 app.innerHTML=`<div class="shell"><header class="topbar"><div class="identity"><div class="mark">${icon}</div><div><div class="eyebrow">ThreadShelf · ${PRODUCT_VERSION}</div><h1>Local Analytics</h1></div></div><div class="top-actions"><span class="pill top-pill"><i class="status-dot"></i>${esc(t('offline'))}</span>${state.preview?`<span class="pill preview-label">${esc(t('synthetic'))}</span>`:''}${action('add-source',t('addSource'),'','primary')}${action('settings',t('appearance'),'','icon-button')}</div></header><nav class="navigation" aria-label="${attr(t('overview'))}">${navigation.map(([key,glyph])=>`<button class="nav-button${workspace===key?' active':''}" data-action="navigate" data-workspace="${key}" aria-current="${workspace===key?'page':'false'}" title="${attr(t(key))}"><span class="nav-icon" aria-hidden="true">${glyph}</span><span class="nav-label">${esc(t(key))}</span></button>`).join('')}<div class="nav-foot">${esc(t('private'))}<br>${esc(t('sourceSafety'))}</div></nav><main class="main"><div class="workspace-head"><div><div class="eyebrow">${esc(t('activeScope'))} · ${esc(t(filters.perspective||'unique'))}</div><h1>${esc(t(workspace))}</h1><p>${esc(t(workspace+'Help'))}</p></div><div class="workspace-controls">${workspace!=='settings'?action('compare',t('compare'))+action('export',t('export'),computing?'disabled':''):action('help',t('help'))}</div></div>${workspace!=='settings'?renderFilterbar():''}${renderJob()}<div class="content" id="workspace-scroll">${state.error?`<div class="notice error" role="alert">${esc(t('errorMessage'))}</div>`:''}${source?.stale?`<div class="notice">${esc(t('stale'))} · ${esc(dateFmt(source.capturedAt))} ${action('refresh-source',t('refresh'),`data-source="${attr(source.id)}"`)}</div>`:''}${workspace==='settings'?renderSettings():state.conversations.length?renderWorkspace():renderEmpty()}</div></main><footer class="footer"><span>${esc(t('sourceSafety'))}</span><span>${computing?esc(t('loading')):summary?fmt(summary.conversations)+' '+esc(t('conversations'))+' · '+fmt(summary.records)+' '+esc(t('segments')):''} ${source?.capturedAt?'· '+esc(t('captured'))+' '+esc(dateFmt(source.capturedAt)):''}</span></footer></div>`;
 restoreViewState(app,previous);renderDialog();if(evidenceOpen)renderEvidence();
}
function renderFilterbar(){
 const collections=[...new Set(state.conversations.flatMap(c=>c.collectionIds||[]))].sort(),providers=[...new Set(state.conversations.map(c=>canonicalPlatform(c.provider)))].sort();
 return `<div class="filterbar"><label class="visually-hidden" for="quick-range">${esc(t('dateRange'))}</label><select id="quick-range" data-quick="range">${options([{value:'all',label:t('allTime')},{value:'7d',label:t('last7')},{value:'30d',label:t('last30')},{value:'year',label:t('calendarYear')},{value:'rolling-year',label:t('rollingYear')},{value:'custom',label:t('custom')}],filters.range)}</select><label class="visually-hidden" for="quick-collection">${esc(t('collections'))}</label><select id="quick-collection" data-quick="collectionIds">${option('',t('collections')+' · '+t('all'),filters.collectionIds?.length===1?filters.collectionIds[0]:'')}${options(collections,filters.collectionIds?.length===1?filters.collectionIds[0]:'')}</select><label class="visually-hidden" for="quick-platform">${esc(t('platforms'))}</label><select id="quick-platform" data-quick="providers">${option('',t('platforms')+' · '+t('all'),filters.providers?.length===1?filters.providers[0]:'')}${options(providers,filters.providers?.length===1?filters.providers[0]:'')}</select><input class="search" type="search" data-quick="search" aria-label="${attr(t('search'))}" placeholder="${attr(t('search'))}" value="${attr(filters.search||'')}">${action('filters',t('advancedFilters'),'','filters-toggle')}${activeCount()?`<span class="active-count">${fmt(activeCount())} ${esc(t('filterCount'))}</span>${action('reset',t('reset'),'','quiet')}`:''}${action('save-view',t('saveView'),'','quiet')}</div>`;
}
function renderJob(){const j=state.job;if(!j?.running)return '';const progress=j.progress!=null?(j.progress<=1?j.progress*100:j.progress):(j.total?j.completed/j.total*100:0);return `<div class="job" role="status"><div class="job-top"><span>${esc(t('capturing'))} ${fmt(j.completed||0)} / ${j.total?fmt(j.total):'…'}</span>${action('cancel-job',t('cancel'))}</div><div class="progress-bar" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(progress)}"><div style="width:${Math.max(0,Math.min(100,progress))}%"></div></div></div>`;}
function renderReaderDiscovery(){const statusKeys={'not-started':'readerNotStarted',checking:'readerChecking',absent:'readerAbsent',available:'readerAvailable',registered:'readerRegistered',suppressed:'readerSuppressed',busy:'readerBusy',invalid:'readerInvalid',unsafe:'readerUnsafe',unavailable:'readerUnavailable',unsupported:'readerUnsupported'},discovery=state.discovery||{},status=state.preview?t('synthetic'):t(statusKeys[discovery.status]||'readerNotStarted');return `<div class="notice reader-discovery" aria-label="${attr(t('readerDiscovery'))}"><strong>${esc(t('readerDiscovery'))}</strong><p role="status">${esc(status)}</p>${discovery.path?`<p class="help">${esc(discovery.path)}</p>`:''}<div class="button-row">${action('discover-reader',t('discoverReader'),state.job?.running?'disabled':'')}</div><p class="help">${esc(t('readerDiscoveryHelp'))}</p></div>`;}
function renderEmpty(){return `<div class="empty"><div class="large-mark" aria-hidden="true">◈</div><h2>${esc(t('noneSources'))}</h2><p>${esc(t('noneHelp'))}</p>${action('add-source',t('addSource'),'','primary')}${renderReaderDiscovery()}<p><small>${esc(t('excludedHelp'))}</small></p></div>`;}
function stat(key,title,category,unit='segments',extra=''){return `<button class="stat ${category||'other'}" data-action="evidence" data-category="${attr(category||'')}" title="${attr(t('viewEvidence'))}"><span class="label">${esc(t(title))}</span><span class="value">${fmt(report?.summary?.[key])}</span><span class="unit">${esc(t(unit))}${extra?' · '+esc(extra):''}</span></button>`;}
function scope(){const s=report?.selection;return `<div class="scope"><span>${esc(t('scope'))}: <strong>${fmt(report?.summary?.conversations)} ${esc(t('conversations'))}</strong></span><span>${esc(t('timezone'))}: <strong>${esc(report?.dateRange?.zone||filters.timeZone)}</strong></span><span>${esc(t('branches'))}: <strong>${esc(t(report?.filters?.branch==='all'?'allBranches':report?.filters?.branch==='alternative'?'alternative':'selected'))}</strong></span>${s?.coveragePeriod?.start?`<span>${esc(t('period'))}: <strong>${esc(s.coveragePeriod.start)} — ${esc(s.coveragePeriod.end)}</strong></span>`:''}</div>`;}
function renderWorkspace(){if(!report)return `<div class="notice" role="status">${esc(t('loading'))}</div>`;return `${computing?`<div class="notice" role="status">${esc(t('previousAnalysis'))}</div>`:''}${scope()}${report.explorer?.warnings?.length?`<div class="notice">${esc(t('explorer.unknownFilters'))} ${report.explorer.warnings.map(w=>esc(w.key||w.code||w)).join(', ')}</div>`:''}${explorerCrossLink()}${report.summary.conversations===0?`<div class="notice"><strong>${esc(t('noMatches'))}</strong><br>${esc(t('noMatchesHelp'))}</div>`:''}${({overview:renderOverview,activity:renderActivity,models:renderModels,content:renderContent,structure:renderStructure,tools:renderTools,quality:renderQuality,explorer:renderExplorerWorkspace})[workspace]?.()||''}`;}
function card(title,body,css='',help=''){return `<section class="card ${css}" data-view-key="card:${attr(title)}"><h2>${esc(t(title))}</h2>${body}${help?(title==='coverage'?`<div class="help safe-markdown">${renderSafeMarkdown(t(help)).html}</div>`:`<p class="help">${esc(t(help))}</p>`):''}</section>`;}
function table(key,columns,limit=0){const original=rows(key),indexes=tableIndex(original);let data=original;const query=tableQueries[key]||'';if(query)data=data.filter(r=>columns.some(c=>String(r[c[0]]||'').toLocaleLowerCase().includes(query.toLocaleLowerCase())));if(key==='conversations')data=[...data].sort((a,b)=>((typeof a[sortKey]==='number'?a[sortKey]:String(a[sortKey]||'').localeCompare(String(b[sortKey]||'')))-(typeof b[sortKey]==='number'?b[sortKey]:0))*(sortOrder==='asc'?1:-1));if(limit)data=data.slice(0,limit);const total=data.length,pageCount=Math.max(1,Math.ceil(total/100)),page=Math.max(0,Math.min(pageCount-1,tablePages[key]||0));tablePages[key]=page;data=data.slice(page*100,(page+1)*100);renderedTableRows[key]=data;
 if(!data.length)return `<div class="chart-empty">${esc(t('noData'))}</div>`;
 return `<div class="table-tools">${action('copy-table',t('copy'),`data-table="${attr(key)}"`,'quiet')}</div><div class="table-wrap${key==='conversations'?' tall':''}" data-view-key="table:${attr(key)}"><table><thead><tr>${columns.map(([field,title])=>`<th scope="col"${['count','value','characters','words','lines','segments','objects','userMessages','responseMessages','interactionDepth','retainedAlternatives','milliseconds','available','total','median','p90','recordedBytes','outputCount'].includes(field)?' class="numeric"':''}>${esc(t(title))}</th>`).join('')}</tr></thead><tbody>${data.map((r,i)=>`<tr class="selectable" tabindex="0" data-action="table-evidence" data-table="${attr(key)}" data-row-id="${attr(r.id||r.label||i)}" data-row-index="${indexes.get(r)}" aria-label="${attr(t('viewEvidence')+' · '+label(r.label||r.title||r.name||r.kind||i))}">${columns.map(([field])=>{const value=r[field];const numerical=typeof value==='number';let v=value==null?t('unavailable'):Array.isArray(value)?value.join(', '):numerical?fmt(value):field==='timestamp'?dateFmt(value):label(value);if(field==='label'&&key==='conversations')v=state.annotations?.aliases?.[r.id]||v;if(field==='capability')v=capLabel(value);return `<td${numerical?' class="numeric"':''}>${esc(v)}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>${total>100?`<div class="table-pagination" aria-label="${attr(t('tablePages'))}">${action('table-page',t('previousPage'),`data-table="${attr(key)}" data-page="${page-1}" ${page===0?'disabled':''}`)}<span role="status">${esc(t('page'))} ${fmt(page+1)} / ${fmt(pageCount)} · ${fmt(page*100+1)}–${fmt(Math.min((page+1)*100,total))} / ${fmt(total)} ${esc(t('tableRows'))}</span>${action('table-page',t('nextPage'),`data-table="${attr(key)}" data-page="${page+1}" ${page===pageCount-1?'disabled':''}`)}</div>`:''}`;
}
function tableCard(key,title,columns,css='full',help=''){return card(title,table(key,columns),css,help);}
function tableToggle(key,columns){return `<details data-view-key="details:${attr(key)}"><summary>${esc(t('showTable'))}</summary>${table(key,columns)}</details>`;}
function bars(key,maxRows=12,measure='count'){return renderHoverBars({id:'bars-'+key,key,rows:rows(key),maxRows,measure,measureLabel:measure==='count'?undefined:t(measure),t:key=>t(key),formatNumber:value=>fmt(value),itemLabel:r=>label(r.label),categoryLabel:value=>value==='system'?t('system'):translatedCategory(value)});}
function timeline(key='timelineDaily'){return renderStackedBarChart({id:key,key,rows:rows(key),title:t('timeline'),t:key=>t(key),formatNumber:value=>fmt(value),categoryLabel:value=>value==='system'?t('system'):translatedCategory(value)});}
function coverageRows(){const labels={timestamps:'timestamp',hourOfDay:'hourly',models:'models',platforms:'platforms',logicalMessages:'user',objects:'objects',text:'characters',thinkingResponseRatio:'thinkingRatio',attachmentSize:'recordedSize',attachmentAvailability:'attachments',durations:'timing',usage:'usage',originalRecords:'normalizedCoverage',thinkingTrace:'trace'};return `<div class="table-wrap"><table><thead><tr><th>${esc(t('metric'))}</th><th class="numeric">${esc(t('coverage'))}</th><th>${esc(t('reliability'))}</th></tr></thead><tbody>${Object.entries(report.coverage||{}).map(([key,c])=>`<tr class="selectable" tabindex="0" data-action="evidence"><td>${esc(t(labels[key]||key))}</td><td class="numeric">${fmt(c.numerator??c.available??c.known)} / ${fmt(c.denominator??c.total)}</td><td>${esc(t(key==='usage'||key==='durations'?'recorded':'derived'))}</td></tr>`).join('')}</tbody></table></div>`;}
function seriesChart(key,field){return renderSeriesChart({key,field,rows:rows(key),title:t(key==='dateModel'?'modelTimeline':'platformTimeline'),t,formatNumber:fmt});}
function renderOverview(){return `<div class="stat-grid">${stat('conversations','conversations','','conversations')}${stat('userMessages','user','user','user')}${stat('thinkingSegments','thinking','thinking')}${stat('responseMessages','response','response','response')}</div><div class="board">${card('timeline',timeline()+tableToggle('timelineDaily',[['date','date'],['count','segments'],['user','user'],['thinking','thinking'],['response','response']]),'full','metricHelp')}${card('composition',bars('composition')+tableToggle('composition',[['label','kind'],['count','segments'],['characters','characters']]),'','compositionRule')}${card('platforms',bars('platforms')+tableToggle('platforms',[['label','platform'],['count','segments'],['characters','characters']]))}${card('coverage',coverageRows(),'full','coverageHelp')}</div>`;}
function calendarDateLabel(day){try{return new Intl.DateTimeFormat(localeFor(state.settings.language),{year:'numeric',month:'long',day:'numeric',timeZone:'UTC'}).format(new Date(day+'T12:00:00Z'));}catch{return day;}}
function renderAnnualCalendar(){
 currentCalendar=buildYearCalendar(report,calendarYear,{locale:localeFor(state.settings.language)});calendarYear=currentCalendar.year;
 const eligible=currentCalendar.days.filter(day=>day.inRange),retained=eligible.find(day=>day.date===calendarFocusDate),focusDate=retained?.date||eligible.find(day=>day.date===calendarSelectedDate)?.date||eligible.find(day=>day.hasEvidence)?.date||eligible[0]?.date;
 calendarFocusDate=focusDate||'';
 const gap='<span class="annual-calendar-gap" aria-hidden="true"></span>',cells=Array.from({length:currentCalendar.offset},()=>gap);
 for(const day of currentCalendar.days){
  const date=calendarDateLabel(day.date),description=date+' · '+(day.inRange?fmt(day.count)+' '+t('segments'):t('calendarOutsideRange'));
  if(!day.inRange){cells.push(`<span class="annual-calendar-outside" title="${attr(description)}" aria-label="${attr(description)}"></span>`);continue;}
  cells.push(`<button type="button" class="annual-calendar-day annual-calendar-level-${day.level}${day.date===calendarSelectedDate?' selected':''}" data-action="calendar-day" data-calendar-date="${day.date}" data-calendar-index="${day.index}" tabindex="${day.date===focusDate?0:-1}" aria-pressed="${day.date===calendarSelectedDate}" aria-label="${attr(description)}" title="${attr(description)}"><span class="visually-hidden">${esc(fmt(day.count))}</span></button>`);
 }
 cells.push(...Array.from({length:currentCalendar.trailingGaps},()=>gap));
 return `<section class="card full annual-calendar-card"><div class="annual-calendar-heading"><div><h2>${esc(t('calendar'))}</h2><p class="help">${esc(t('segments'))} · ${esc(currentCalendar.yearText)}</p></div><label class="annual-calendar-year"><span>${esc(t('calendarYearSelect'))}</span><select data-calendar-year aria-label="${attr(t('calendarYearSelect'))}">${currentCalendar.years.map(year=>option(String(year),String(year),String(calendarYear))).join('')}</select></label></div><div class="annual-calendar-scroll"><div class="annual-calendar-months">${currentCalendar.months.map(month=>`<span>${esc(month.label)}</span>`).join('')}</div><div class="annual-calendar-layout"><div class="annual-calendar-weekdays" aria-hidden="true">${currentCalendar.weekdays.map(day=>`<span>${esc(day)}</span>`).join('')}</div><div class="annual-calendar-mosaic" style="--annual-calendar-columns:${currentCalendar.columnCount}" role="group" aria-label="${attr(t('calendar')+' · '+currentCalendar.yearText)}" aria-describedby="annual-calendar-keyboard">${cells.join('')}</div></div></div><div class="annual-calendar-legend"><span>${esc(t('calendarLess'))}</span>${[0,1,2,3,4].map(level=>`<span class="annual-calendar-key annual-calendar-level-${level}" aria-hidden="true"></span>`).join('')}<span>${esc(t('calendarMore'))}</span><span class="annual-calendar-legend-spacer"></span><span>${esc(t('calendarHelp'))}</span></div><p id="annual-calendar-keyboard" class="visually-hidden">${esc(t('calendarKeyboardHelp'))}</p>${tableToggle('timelineDaily',[['date','date'],['count','segments']])}</section>`;
}
function renderActivity(){const key=timelineMode==='weekly'?'timelineWeekly':timelineMode==='monthly'?'timelineMonthly':'timelineDaily';return `<div class="stat-grid">${stat('activeDays','activeDays','','days')}${stat('longestStreak','streak','','days')}${stat('datedRecords','timestamp','','segments')}${stat('undatedRecords','undated','','segments')}</div><div class="board">${card('timeline',`<div class="button-row">${['daily','weekly','monthly'].map(m=>action('timeline-mode',t(m),`data-mode="${m}"`,timelineMode===m?'active':'')).join('')}</div>${timeline(key)}${tableToggle(key,[['date','date'],['count','segments']])}`,'full')}${renderAnnualCalendar()}${card('hourly',bars('hour',24)+tableToggle('hour',[['label','hourly'],['count','segments']]),'','datePrecisionHelp')}${card('weekdays',bars('weekday',7)+tableToggle('weekday',[['label','weekdays'],['count','segments']]))}${card('activity',`<dl class="definition-list"><dt>${esc(t('busiest'))}</dt><dd>${esc(report.summary.busiestDay?.date||t('unavailable'))} · ${fmt(report.summary.busiestDay?.count)}</dd><dt>${esc(t('averageActive'))}</dt><dd>${fmt(report.summary.averagePerActiveDay)} ${esc(t('segments'))}</dd><dt>${esc(t('averageCalendar'))}</dt><dd>${fmt(report.summary.averagePerCalendarDay)} ${esc(t('segments'))}</dd></dl>`,'full')}${card('coverage',coverageRows(),'full','coverageHelp')}${renderPreviousPeriod()}</div>`;}
function renderPreviousPeriod(){const p=report.previousPeriod;if(!p)return '';return card('previousPeriod',`<p class="help">${esc(p.dateRange.startDay)} — ${esc(p.dateRange.endDay)} · ${fmt(p.calendarDays)} ${esc(t('days'))}</p><div class="table-wrap"><table><thead><tr><th>${esc(t('metric'))}</th><th>${esc(t('scopeUnchanged'))}</th><th>${esc(t('previousPeriod'))}</th><th>${esc(t('difference'))}</th></tr></thead><tbody>${(p.comparison||[]).slice(0,12).map(v=>{const key=v.metric;return `<tr><td>${esc(summaryLabel(key))}</td><td class="numeric">${fmt(v.current??v.left)}</td><td class="numeric">${fmt(v.previous??v.right)}</td><td class="numeric">${fmt(v.difference??v.delta)}</td></tr>`}).join('')}</tbody></table></div>`,'full');}
function renderModels(){return `<div class="notice">${esc(t('modelFilterHelp'))}</div><div class="board">${card('model',bars('models')+tableToggle('models',[['label','model'],['count','segments'],['characters','characters']]))}${card('platforms',bars('platforms')+tableToggle('platforms',[['label','platform'],['count','segments'],['characters','characters']]))}${tableCard('modelDevelopers','modelDeveloper',[['label','modelDeveloper'],['count','segments']],'full')}${tableCard('modelChanges','modelChanges',[['label','change'],['conversationId','annotationTarget'],['count','count']])}${tableCard('modelFamilies','modelFamilies',[['label','modelFamilies'],['count','segments']], 'full')}${card('modelTimeline',seriesChart('dateModel','model')+tableToggle('dateModel',[['date','date'],['model','model'],['count','segments']]),'full')}${tableCard('dateModel','modelTimeline',[['date','date'],['model','model'],['count','segments']])}${card('platformTimeline',seriesChart('datePlatform','provider')+tableToggle('datePlatform',[['date','date'],['provider','platform'],['count','segments']]),'full')}${tableCard('datePlatform','platformTimeline',[['date','date'],['provider','platform'],['count','segments']])}${card('coverage',coverageRows(),'full','coverageHelp')}</div>`;}
function renderContent(){const s=report.summary;return `<div class="stat-grid">${stat('characters','characters','','characters')}${stat('codeBlocks','code','','code')}${stat('codeLines','codeLines','','lines')}${stat('attachments','attachments','','attachments')}</div><div class="board">${card('languages',bars('codeLanguages')+tableToggle('codeLanguages',[['language','language'],['count','code'],['lines','lines']]),'','lengthRule')}${card('textVolumes',bars('composition',12,'characters')+tableToggle('composition',[['label','kind'],['characters','characters'],['words','words']]),'','compositionRule')}${tableCard('thinkingRepresentations','thinking',[['label','kind'],['count','segments'],['characters','characters']],'full','noThinking')}${tableCard('lengthDistribution','lengths',[['label','kind'],['count','segments'],['median','median'],['p90','p90'],['maximum','maximum']])}${card('thinkingRatio',`<button class="stat thinking" data-action="evidence" data-category="thinking"><span class="value">${fmt(s.thinkingResponseRatio)}</span><span class="label">${esc(t('characterRatio'))}</span></button><p class="help">${esc(t('noThinking'))}</p>`)}${card('domains',bars('domains')+tableToggle('domains',[['label','domains'],['count','count']]))}${tableCard('attachmentTypes','attachmentTypes',[['label','kind'],['count','attachments'],['recordedBytes','bytes']],'full','bytesUnavailable')}${tableCard('attachments','attachments',[['label','kind'],['bytes','recordedSize'],['width','value'],['height','value'],['availability','status']])}${card('links',`<dl class="definition-list"><dt>${esc(t('links'))}</dt><dd>${fmt(s.links)}</dd><dt>${esc(t('citations'))}</dt><dd>${fmt(s.structuredReferences)}</dd><dt>${esc(t('tables'))}</dt><dd>${fmt(s.markdownTables)}</dd><dt>${esc(t('code'))} / ${esc(t('characters'))}</dt><dd>${fmt(s.codeCharacters)} / ${fmt(s.characters)}</dd></dl>`,'full')}</div>`;}
