function sourceList(){if(!state.sources.length)return `<p class="help">${esc(t('sourceEmpty'))}</p>`;return state.sources.map(s=>`<article class="source-item"><div class="source-title"><strong>${esc(s.name||s.id)}</strong><span class="pill">${esc(t(s.stale?'stale':s.status==='unavailable'?'sourceUnavailable':s.status==='registered'?'sourceEmpty':s.status==='partial'?'partial':'complete'))}</span></div><dl class="source-details"><dt>${esc(t('sourceId'))}</dt><dd>${esc(s.id)}</dd><dt>${esc(t('captured'))}</dt><dd>${esc(dateFmt(s.capturedAt))}</dd><dt>${esc(t('snapshot'))}</dt><dd>${esc(s.snapshotId||t('unknown'))}</dd><dt>${esc(t('conversations'))}</dt><dd>${fmt(s.conversationCount)}</dd><dt>${esc(t('connection'))}</dt><dd>${esc(s.kind==='reader'?t('reader'):s.kind==='files'?t('files'):t('directory'))}</dd>${s.path?`<dt>${esc(t('sourceNative'))}</dt><dd>${esc(s.path)}</dd>`:''}</dl><div class="source-actions">${action('refresh-source',t('refresh'),`data-source="${attr(s.id)}"`)}${action('rebuild-source',t('rebuild'),`data-source="${attr(s.id)}"`)}${bridge.captureHistory?action('capture-history',t('explorer.captureHistory'),`data-source="${attr(s.id)}"`):''}${action('remove-source',t('remove'),`data-source="${attr(s.id)}"`,'danger')}</div></article>`).join('');}
