function renderHistorySettings(){if(!bridge.captureHistory)return '';const h=state.settings.history||{};return card('explorer.captureHistory',`<p class="help">${esc(t('explorer.historyHelp'))}</p><form id="history-settings-form"><div class="checks"><label><input type="checkbox" name="enabled"${checked(h.enabled)}> ${esc(t('explorer.historyEnabled'))}</label></div><div class="form-grid"><label class="field"><span>${esc(t('explorer.retainedCaptures'))}</span><input type="number" name="maxCaptures" min="0" max="20" value="${attr(h.maxCaptures??3)}"></label><label class="field"><span>${esc(t('explorer.historyMegabytes'))}</span><input type="number" name="maxMegabytes" min="1" max="4096" value="${attr((h.maxBytes||134217728)/1048576)}"></label></div><div class="button-row"><button type="submit" class="primary">${esc(t('save'))}</button></div></form>`,'full');}
