 if(name==='history-compare'){const form=document.getElementById('capture-history-pair'),data=new FormData(form);const diff=await run(()=>bridge.compareCaptureHistory(dialog.sourceId,data.get('leftId'),data.get('rightId'),mergedFilters()));if(diff){dialog.diff=diff;explorerConfig.history={enabled:true,diff,sourceId:dialog.sourceId};calculate();renderDialog();}}
 if(name==='storage-usage'){openDialog('storage-usage',{loading:true});const usage=await run(()=>bridge.storageUsage());if(dialog?.type==='storage-usage'){dialog.usage=usage;dialog.loading=false;renderDialog();}}
 if(name==='navigate'){workspace=target.dataset.workspace;closeDialog();evidenceOpen=false;document.querySelector('.evidence-panel')?.remove();render();}
 if(name==='settings')openDialog('appearance');
 if(name==='add-source')openDialog('add-source');
