 if(name==='choose-source'){closeDialog();const result=await run(()=>bridge.chooseSource(target.dataset.kind));if(result?.preview)showToast(t('previewSource'));}
 if(name==='filters')openDialog('filters');
 if(name==='reset'){clearTimeout(searchTimer);document.querySelector('[data-quick=search]').value='';filters={...defaults,timeZone:state.settings.timezone||'local'};calculate();}
