 if(name==='save-view')openDialog('save-view');
 if(name==='load-view'){const v=state.savedViews.find(v=>v.id===target.dataset.view);if(v){filters={...v.filters};clearTimeout(searchTimer);const input=document.querySelector('[data-quick=search]');if(input)input.value=filters.search||'';workspace='overview';calculate();}}
 if(name==='export')openDialog('export');
 if(name==='help')openDialog('help');
 if(name==='close-dialog')closeDialog();
 if(name==='refresh-source')await run(()=>bridge.refresh(target.dataset.source));
 if(name==='rebuild-source')await run(()=>bridge.rebuildIndexes?bridge.rebuildIndexes(target.dataset.source):bridge.rebuild(target.dataset.source));
 if(name==='cancel-job')await run(()=>bridge.cancel(),'cancelled');
 if(name==='remove-source')openDialog('confirm',{title:t('remove'),text:t('confirmRemove'),confirm:async()=>{await run(()=>bridge.removeSource(target.dataset.source),'sourceRemoved');}});
 if(name==='clear-cache')openDialog('confirm',{title:t('clearCache'),text:t('clearConfirm'),confirm:async()=>{await run(()=>bridge.clearCache(),'cacheCleared');}});
 if(name==='confirm-action'){const fn=dialog.confirm;closeDialog();await fn();}
 if(name==='calendar-day'){if(computing){showToast(t('loading'));return;}const day=currentCalendar?.days[Number(target.dataset.calendarIndex)];if(!day||day.date!==target.dataset.calendarDate||!day.inRange)return;calendarSelectedDate=day.date;calendarFocusDate=day.date;for(const button of document.querySelectorAll('.annual-calendar-day')){const active=button.dataset.calendarDate===day.date;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active));button.tabIndex=active?0:-1;}if(day.hasEvidence&&day.rowIndex!==null)openEvidence({table:'timelineDaily',rowIndex:day.rowIndex},'',calendarDateLabel(day.date)+' · '+fmt(day.count)+' '+t('segments'));else{evidenceOpen=false;evidence=[];evidenceTotal=0;evidenceRequestId=++requestId;document.querySelector('.evidence-panel')?.remove();showToast(calendarDateLabel(day.date)+' · '+t('calendarNoActivity'));}return;}
 if(name==='timeline-mode'){timelineMode=target.dataset.mode;restoreScroll(render);}
